import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(new BufferedInputStream(System.in));
        int n = sc.nextInt();
        double d = sc.nextDouble();

        double[] position = new double[n];
        double[] charge = new double[n];

        for (int i = 0; i < n; i++) {
            position[i] = sc.nextDouble();
            charge[i] = sc.nextDouble();
        }

        double[] dp = new double[n];
        Arrays.fill(dp, Double.POSITIVE_INFINITY);
        dp[0] = 0.0;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double distance = position[j] - position[i];
                double time = distance * distance / charge[i];
                dp[j] = Math.min(dp[j], dp[i] + time);
            }
        }

        double answer = Double.POSITIVE_INFINITY;
        for (int i = 0; i < n; i++) {
            double distance = d - position[i];
            answer = Math.min(answer, dp[i] + distance * distance / charge[i]);
        }

        System.out.printf(Locale.US, "%.3f%n", answer);
    }
}
